solution:
fn wrap_in_vec[T](value: T) -> Vec[T] {
  var v = Vec[T]();
  v.push(value);
  return v;
}

fn unwrap_first[T](v: &Vec[T]) -> T
  requires: v.len() > 0;
{
  return v[0];
}

fn main() -> Int {
  let wrapped = wrap_in_vec[Int](42);
  return unwrap_first[Int](&wrapped);
}
